    inline const Info* find(uint64_t item)
    {
        size_t lo = 0, hi = sizeof(kTable) / sizeof(kTable[0]);
        while (lo < hi) {
            const size_t mid = (lo + hi) / 2;
            if (kTable[mid].item < item) lo = mid + 1;
            else hi = mid;
        }
        return lo < sizeof(kTable) / sizeof(kTable[0]) && kTable[lo].item == item ? &kTable[lo] : nullptr;
    }
